    "m54fa2e1046df": "Teilweise Punkterückgewinnung",
    "m6df9d27b8aa2": "Der angegebene Betrag wird von den aktuell verbleibenden Teampunkten des Mitglieds abgezogen, wobei den zuletzt abgelaufenen ungenutzten Punkten Vorrang eingeräumt wird.",
