    "m3333f1501053": "Es können maximal {value1} Bilder hochgeladen werden, die ersten {value2} Bilder wurden ausgewählt",
    "ma8f60f0523a2": "Bitte melden Sie sich an, bevor Sie die Bildgenerierungsfunktion nutzen. Registrieren Sie neue Benutzer, um Bonuspunkte zu erhalten!",
    "m673bfd286541": "Bitte geben Sie das Aufforderungswort ein",
