    "m09ecf857f810": "Melden Sie sich an und sammeln Sie Punkte!",
    "mc87ec99f0100": "Neue Benutzer können bei der Registrierung Bonuspunkte sammeln und jetzt mit der Erstellung beginnen~",
    "m17e5403abcd9": "Jetzt registrieren/einloggen",
    "m2f37945f2f3a": "⚡VIP-Benutzer",
