    "me0d525557b5d": "Galerie exportieren",
    "m12185c19647a": "Galerie aktualisieren",
    "m4faff5e082d6": "Geben Sie links das Eingabewort ein und klicken Sie auf die Schaltfläche „Generieren“, um ein einzigartiges Bild zu erstellen",
    "m583a2e69a3a0": "HD-Bilder werden erzeugt...",
    "m45dda25ef060": "Wunderbare Werke werden in Kürze präsentiert",
    "m177bfb1f2031": "Sie können weiterhin erstellen. Neue Erstellungen haben keinen Einfluss auf die ursprüngliche Aufgabengenerierung",
