    m62867204bb0a: "Die Textelemente überschreiten die Obergrenze von {value1} und die Untertitelergebnisse wurden beibehalten; Bitte löschen Sie etwas Text und warten Sie auf das automatische Schreiben",
    m8c995cbd2fdc: "Ungültiger Untertitel-Aufgabentyp",
    m7e8828ee53e0: "E7009 Der Untertitel-Aufgabenstatus ist vorübergehend nicht verfügbar und wird erneut versucht. Bitte generieren Sie es nicht erneut.",
    m0f6d729963de: "{value1} Untertitelerkennung fehlgeschlagen, Punkte wurden zurückgegeben",
    mac475614dc2c: "E7099 Das Ergebnis der Untertitelaufgabe muss bestätigt werden. Bitte nicht erneut generieren.",
    me428cb1fa367: "E7009 Die aktuelle Umgebung unterstützt das Lesen von Untertitelergebnissen nicht.",
    m8d69d8ef45d9: "E7009 Untertitelergebnisse konnten nicht gelesen werden. Versuchen Sie es noch einmal",
    m9094f621029b: "E7009 Für diesen Clip können keine Untertitel generiert werden. Bitte bestätigen Sie, dass der Clip Audio enthält und intelligente Untertitel aktiviert sind",
    mefa4d618895f: "E7099 Der Übermittlungsstatus muss bestätigt werden. Die ursprüngliche Aufgabe wird abgefragt. Bitte generieren Sie es nicht erneut.",
    m5103d6174afd: "E7009 Die Untertitel-Aufgabennummer wurde nicht gespeichert. Bitte versuchen Sie erneut zu speichern, bevor Sie die Generierung bestätigen.",
    m936d73e9c365: "Quadratisch",
